SELECT 'batch_032_60e8f228_wav_10' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-1c1d6c3a-6ac','sm-upload-2cc2cded-f96','sm-upload-2ed4a91f-50f','sm-upload-54a04d18-b6d','sm-upload-85febee1-add','sm-upload-8c8ff71c-39c','sm-upload-8dac0faa-885','sm-upload-a4e20343-e35','sm-upload-f35ebe3d-fb5','sm-upload-f8b47093-229') AND album_id='al-18ec76e1cfd7e7dc3e8258b060e8f228') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-1c1d6c3a-6ac','sm-upload-2cc2cded-f96','sm-upload-2ed4a91f-50f','sm-upload-54a04d18-b6d','sm-upload-85febee1-add','sm-upload-8c8ff71c-39c','sm-upload-8dac0faa-885','sm-upload-a4e20343-e35','sm-upload-f35ebe3d-fb5','sm-upload-f8b47093-229') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-18ec76e1cfd7e7dc3e8258b060e8f228' AND name='哈利波特·学院印象曲') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-18ec76e1cfd7e7dc3e8258b060e8f228') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-18ec76e1cfd7e7dc3e8258b060e8f228') AS calculated_size;
